-- c3ccf713 | ما هو مفهوم "أهل الحل والعقد" في السياسة الشرعية؟
UPDATE qa_questions SET
  answer = 'هم «أَهْلُ الِاخْتِيَارِ» الذين تُعقَد بهم الإمامة؛ قال الماوردي: «والإمامة تنعقد من وجهين: أحدهما: باختيار أهلِ العَقْدِ والحَلِّ»، والثاني بعهد الإمام من قبلُ. وشروطُهم عنده ثلاثة: «الْعَدَالَةُ الْجَامِعَةُ لِشُرُوطِهَا»، و«الْعِلْمُ الَّذِي يُتَوَصَّلُ بِهِ إلَى مَعْرِفَةِ مَنْ يَسْتَحِقُّ الْإِمَامَةَ»، و«الرَّأْيُ وَالْحِكْمَةُ الْمُؤَدِّيَانِ إلَى اخْتِيَارِ مَنْ هُوَ لِلْإِمَامَةِ أَصْلَحُ، وَبِتَدْبِيرِ الْمَصَالِحِ أَقْوَمُ وَأَعْرَفُ». وقد «اخْتَلَفَ الْعُلَمَاءُ فِي عَدَدِ مَنْ تَنْعَقِدُ بِهِ» الإمامةُ منهم «عَلَى مَذَاهِبَ شَتَّى»: فطائفةٌ لا تُنعقدها إلا بجمهورهم من كلّ بلد، وطائفةٌ تكتفي بخمسةٍ يجتمعون على عقدها.',
  reference = 'الأحكام السلطانية للماوردي: ص١٧-١٨ (فصل في بيان حكم الخلافة)، وص٢١-٢٣ (فصل بم تنعقد الإمامة) | الكلمات المفتاحية: أهل الحل والعقد',
  evidence = 'قال الماوردي في شروطهم: «فَأَمَّا أَهْلُ الِاخْتِيَارِ فَالشُّرُوطُ الْمُعْتَبَرَةُ فِيهِمْ ثَلَاثَةٌ: أَحَدُهَا: الْعَدَالَةُ الْجَامِعَةُ لِشُرُوطِهَا» (ص١٧)، «وَالثَّانِي: الْعِلْمُ الَّذِي يُتَوَصَّلُ بِهِ إلَى مَعْرِفَةِ مَنْ يَسْتَحِقُّ الْإِمَامَةَ عَلَى الشُّرُوطِ الْمُعْتَبَرَةِ فِيهَا. وَالثَّالِثُ: الرَّأْيُ وَالْحِكْمَةُ الْمُؤَدِّيَانِ إلَى اخْتِيَارِ مَنْ هُوَ لِلْإِمَامَةِ أَصْلَحُ، وَبِتَدْبِيرِ الْمَصَالِحِ أَقْوَمُ وَأَعْرَفُ» (ص١٨). وفي وظيفتهم: «والإمامة تنعقد من وجهين: أحدهما: باختيار أهلِ العَقْدِ والحَلِّ» (ص٢١)، «وَالثَّانِي: بِعَهْدِ الْإِمَامِ مِنْ قَبْلُ» (ص٢٢). وفي عددهم: «فَقَدْ اخْتَلَفَ الْعُلَمَاءُ فِي عَدَدِ مَنْ تَنْعَقِدُ بِهِ» (ص٢٢) «الْإِمَامَةُ مِنْهُمْ عَلَى مَذَاهِبَ شَتَّى، فَقَالَتْ طَائِفَةٌ: لَا تَنْعَقِدُ إلَّا بِجُمْهُورِ أَهْلِ الْعَقْدِ وَالْحَلِّ مِنْ كُلِّ بَلَدٍ» ... «وَقَالَتْ طَائِفَةٌ أُخْرَى: أَقَلُّ مَنْ تَنْعَقِدُ بِهِ مِنْهُمُ الْإِمَامَةُ خَمْسَةٌ» (ص٢٣).',
  verification_status = 'verified'
WHERE id = 'c3ccf713-bd40-438a-a572-c5c98f7c5cac'
  AND reference = 'الأحكام السلطانية للماوردي | الكلمات المفتاحية: أهل الحل والعقد'
  AND evidence = 'مبحث فقهي مبسوط في كتب السياسة الشرعية والأحكام السلطانية.'
  AND answer = 'أهل العلم والرأي والوجاهة في الأمة الذين يُعتَدّ بهم في اختيار الحاكم أو مبايعته أو مشورته في الأمور المصيرية العامة، وهو مفهوم اجتهادي تطوّر مع تطور أنظمة الحكم.';

-- bcf851d7 | ما هو نظام الحسبة في الحكم الإسلامي التاريخي؟
UPDATE qa_questions SET
  answer = 'ولايةٌ شرعية حدُّها عند الماوردي أعمُّ من مراقبة الأسواق: «الحسبة: هي أمر بالمعروف إذا ظهر تركه، ونهي عن المنكر إذا أظهر فعله»، وموقعُها أنها «واسطة بين أحكام القضاء وأحكام المظالم». فيسمع واليها الدعوى في ثلاثة أنواع فحسب: «بخس وتطفيف في كيل أو وزن»، و«غش أو تدليس في مبيع أو ثمن»، و«مطل وتأخير لدَيْن مستحق مع المكنة»، وليس له أن «يسمع بينة على إثبات الحق» ولا «أن يحلف يمينًا على نفي الحق». و«له أن يعزِّر في المنكرات الظاهرة لا يتجاوز إلى الحدود»، و«له اجتهاد رأيه فيما تعلق بالعرف دون الشرع؛ كالمقاعد في الأسواق». وشرطُ واليها أن يكون «حرًّا عدلًا، ذا رأي وصرامة وخشونة في الدين، وعلم بالمنكرات الظاهرة».',
  reference = 'الأحكام السلطانية للماوردي: ص٣٤٩-٣٥٣ (الباب العشرون في أحكام الحسبة) | الكلمات المفتاحية: نظام الحسبة',
  evidence = 'قال الماوردي في صدر الباب: «الحسبة: هي أمر بالمعروف إذا ظهر تركه، ونهي عن المنكر إذا أظهر فعله» (ص٣٤٩). وفي موقعها من الولايات: «واعلم أن الحسبة واسطة بين أحكام القضاء وأحكام المظالم»، وسماعُ الدعوى فيها مقصورٌ على ثلاثة: «أحدها: أن يكون فيما يتعلق ببخس وتطفيف في كيل أو وزن. والثاني: ما يتعلق بغش أو تدليس في مبيع أو ثمن. والثالث: فيما يتعلق بمطل وتأخير لدَيْن مستحق مع المكنة» (ص٣٥٢)، «فلا يجوز للمحتسب أن يسمع بينة على إثبات الحق، ولا أن يحلف يمينًا على نفي الحق» (ص٣٥٣). وفي سلطته وشرطه: «له أن يعزِّر في المنكرات الظاهرة لا يتجاوز إلى الحدود» و«له اجتهاد رأيه فيما تعلق بالعرف دون الشرع؛ كالمقاعد في الأسواق»، و«من شروط والي الحسبة أن يكون حرًّا عدلًا، ذا رأي وصرامة وخشونة في الدين، وعلم بالمنكرات الظاهرة» (ص٣٥٠).',
  verification_status = 'verified'
WHERE id = 'bcf851d7-d833-4a93-a92e-4b9dac13bd6c'
  AND reference = 'الأحكام السلطانية للماوردي | الكلمات المفتاحية: نظام الحسبة'
  AND evidence = 'مذكورة في كتب النظم الإسلامية التاريخية كالأحكام السلطانية.'
  AND answer = 'وظيفة إشرافية تاريخية لمراقبة الأسواق والأخلاق العامة وتطبيق الأمر بالمعروف والنهي عن المنكر بصلاحية شبه قضائية سريعة، شبيهة إلى حد ما بأجهزة حماية المستهلك المعاصرة.';

-- 59d3a588 | من هم أشهر مفسري القرآن قديمًا؟
UPDATE qa_questions SET
  answer = 'من الصحابة: عبد الله بن عباس رضي الله عنهما، «ابن عم النبي صلى الله عليه وسلم»، وله تفسيرٌ «رواه عنه مجاهد»، وقد ضمَّه النبي ﷺ وقال: «اللَّهُمَّ عَلِّمْهُ الْكِتَابَ». ومن الأئمة المصنِّفين — كما في طبقات المفسرين للداودي —: محمد بن جرير الطبري (ت ٣١٠هـ) «الإمام، صاحب التصانيف المشهورة»، والبغوي الملقَّب «محيي السنة» (ت ٥١٦هـ) صاحب «معالم التنزيل في التفسير»، والقرطبي (ت ٦٧١هـ) الذي «جمع في تفسير القرآن كتابا كبيرا في خمسة عشر مجلدا»، وابن كثير (ت ٧٧٤هـ) الذي قال فيه شيخه: «فقيه متفنن ومحدث متقن ومفسر نقاد».',
  reference = 'طبقات المفسرين للداودي: ج١/ص٢٣٩ (عبد الله بن عباس)، وج١/ص١٦١-١٦٢ (البغوي)، وج١/ص١١٢-١١٣ (ابن كثير)، وج٢/ص٦٩-٧٠ (القرطبي)، وج٢/ص١١٠ وص١١٣ وص١١٧ (الطبري)؛ صحيح البخاري (ط السلطانية): ٧٥ (ج١/ص٢٦، باب قول النبي ﷺ اللهم علمه الكتاب) | الكلمات المفتاحية: أشهر المفسرين',
  evidence = 'في ترجمة عبد الله بن عباس عند الداودي: «ابن عم النبي صلى الله عليه وسلم، سمع النبي صلى الله عليه وسلم، وروى عن جماعة من الصحابة»، وله تفسيرٌ «رواه عنه مجاهد، ورواه عن مجاهد، حميد بن قيس»، و«مات بالطائف سنة ثمان، ويقال سنة تسع وستين» (ج١/ص٢٣٩)؛ وفي البخاري عنه: «ضَمَّنِي رَسُولُ اللهِ ﷺ وَقَالَ: اللَّهُمَّ عَلِّمْهُ الْكِتَابَ» (٧٥). وفي الطبري: «الإمام، صاحب التصانيف المشهورة» (ج٢/ص١١٠)، وقول أبي حامد الأسفراييني: «لو سافر رجل إلى الصّين، حتى يحصل له كتاب تفسير محمد بن جرير، لم يكن ذلك كثيرا» (ج٢/ص١١٣)، ووفاتُه «لأربع بقين من شوال سنة عشر وثلاثمائة» (ج٢/ص١١٧). وفي البغوي: «ويلقب محيي السنة»، «كان إماما في التفسير، إماما في الحديث، إماما في الفقه، جليلا ورعا زاهدا»، وله «معالم التنزيل في التفسير»، و«مات في شوال سنة ست عشرة وخمسمائة» (ج١/ص١٦١-١٦٢). وفي القرطبي: «جمع في تفسير القرآن كتابا كبيرا في خمسة عشر مجلدا» (ج٢/ص٦٩)، «وبها توفى في ليلة الاثنين التاسع من شوال سنة إحدى وسبعين وستمائة» (ج٢/ص٧٠). وفي ابن كثير: «كان قدوة العلماء والحفاظ وعمدة أهل المعاني والألفاظ»، وقول شيخه فيه: «فقيه متفنن ومحدث متقن ومفسر نقاد» (ج١/ص١١٢)، و«مات في يوم الخميس السادس والعشرين من شعبان سنة أربع وسبعين وسبعمائة» (ج١/ص١١٣).',
  verification_status = 'verified'
WHERE id = '59d3a588-ed29-49c0-8c80-bd2a3ecf7924'
  AND reference = 'طبقات المفسرين للداودي | الكلمات المفتاحية: أشهر المفسرين'
  AND evidence = 'ذُكرت تراجمهم ومناهجهم في كتب طبقات المفسرين.'
  AND answer = 'من أشهرهم ابن عباس رضي الله عنه (ترجمان القرآن) من الصحابة، والطبري وابن كثير والقرطبي والبغوي من المتأخرين، ولكل منهم منهجه الخاص في التفسير.';

-- 96ba12ca | ما هو تفسير الجلالين؟
UPDATE qa_questions SET
  answer = 'تفسيرٌ مختصر لجلال الدين المحلي (ت ٨٦٤هـ) وجلال الدين السيوطي، وسُمّي بالجلالين نسبةً إلى لقبهما وهما جلالان. وابتدأه المحلي من غير أوّل القرآن: «كتب منه من أول الكهف إلى آخر القرآن» ثم مات قبل إتمامه، فكتب السيوطي النصف الأوّل وسمّى صنيعه تكملةً، إذ يقول: «واعتمدت عليه أنا في تكملته». ويتميّز بالإيجاز؛ فكتبُ المحلي — كما وصفها الداودي — «في غاية الاختصار والتحرر والتنقيح، وسلاسة العبارة وحسن المزج».',
  reference = 'طبقات المفسرين للداودي: ج٢/ص٨٤-٨٥ (ترجمة جلال الدين المحلي)، وج١/ص١٠١ (نقل السيوطي عن تكملته) | الكلمات المفتاحية: تفسير الجلالين',
  evidence = 'في ترجمة «محمد بن أحمد بن محمد بن إبراهيم بن أحمد الامام العلامة أوحد الأئمة جلال الدين المحلي الشافعي»: «ولد بمصر سنة إحدى وتسعين وسبعمائة»، وكتبُه «في غاية الاختصار والتحرر والتنقيح، وسلاسة العبارة وحسن المزج» (ج٢/ص٨٤)، ثم: «وأجلّ كتبه التي لم تكمل تفسير القرآن العظيم كتب منه من أول الكهف إلى آخر القرآن. مات أول يوم من سنة أربع وستين وثمانمائة» (ج٢/ص٨٥). ونقل الداودي قول شيخه السيوطي في ترجمة الكواشي: «وعليه اعتمد الشيخ جلال الدّين المحليّ في تفسيره، واعتمدت عليه أنا في تكملته» (ج١/ص١٠١).',
  verification_status = 'verified'
WHERE id = '96ba12ca-8b31-4080-a9d4-fefb7db810a6'
  AND reference = 'طبقات المفسرين للداودي | الكلمات المفتاحية: تفسير الجلالين'
  AND evidence = 'من أشهر كتب التفسير المختصر، مذكور في كتب طبقات المفسرين.'
  AND answer = 'تفسير مختصر مشهور بدأه جلال الدين المحلي وأتمه جلال الدين السيوطي (فسُمي بذلك نسبة لهما)، يتميز بالإيجاز الشديد المناسب للمبتدئين في طلب التفسير.';
